import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"RFC 0073 — Standalone usage of @sovereignfs/ui outside the plugin runtime","description":"","frontmatter":{},"headers":[],"relativePath":"rfcs/0073-standalone-ui-package.md","filePath":"rfcs/0073-standalone-ui-package.md"}'),s={name:"rfcs/0073-standalone-ui-package.md"};function i(d,e,r,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="rfc-0073-—-standalone-usage-of-sovereignfs-ui-outside-the-plugin-runtime" tabindex="-1">RFC 0073 — Standalone usage of <code>@sovereignfs/ui</code> outside the plugin runtime <a class="header-anchor" href="#rfc-0073-—-standalone-usage-of-sovereignfs-ui-outside-the-plugin-runtime" aria-label="Permalink to &quot;RFC 0073 — Standalone usage of `@sovereignfs/ui` outside the plugin runtime&quot;">​</a></h1><p><strong>Status:</strong> Implemented<br><strong>Date:</strong> July 2026<br><strong>Author:</strong> External contributor (submitted for consideration; adapted to repository conventions)<br><strong>Scope:</strong> <code>docs/design-system.md</code>. No dependency on <code>@sovereignfs/sdk</code> or any RFC governing plugin composition. No <code>packages/ui</code> code changes — verification confirmed none were needed.<br><strong>Incorporated into plan:</strong> Yes — epic task 9.17.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Make <code>@sovereignfs/ui</code> usable as an ordinary npm dependency in an external app that is not a Sovereign plugin and does not run inside the Sovereign runtime shell — with its design tokens, components, and hooks all working correctly without any runtime-injected globals. Most of the technical groundwork already exists (see Current state); this RFC is mainly about stating and documenting a guarantee that today is true by accident, not by contract.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p><code>@sovereignfs/ui</code> is a well-scoped, accessibility-conscious component library (<code>Button</code>, <code>FormField</code>, <code>TagInput</code>, <code>StatusBadge</code>, <code>Icon</code>, mobile interaction hooks, etc.) that&#39;s a good fit for apps well beyond Sovereign plugins. Today the documented usage pattern assumes the component tree is mounted inside the Sovereign runtime shell, which injects the <code>--sv-*</code> design token stylesheet globally. There is no stated compatibility guarantee for a standalone consumer, and no explicit confirmation that components/hooks (e.g. <code>useIsMobile</code>, <code>useLongPress</code>) have no hidden dependency on runtime-provided context.</p><p>This matters directly for a separate standalone app under active development that wants visual consistency with the Sovereign ecosystem for its own admin/curator-facing interface, without becoming a plugin itself.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><p>The package is closer to standalone-ready than the original draft assumed — this RFC corrects that and scopes the remaining gap precisely:</p><ul><li><code>packages/ui/package.json</code> is <strong>already published-shaped</strong>: not <code>private</code>, <code>publishConfig.access: &quot;public&quot;</code>, version <code>0.41.0</code>, and <code>exports</code> already declares a standalone tokens entry point (<code>&quot;./tokens.css&quot;: &quot;./src/tokens.css&quot;</code>, plus <code>./tokens/primitives.css</code> and <code>./tokens/semantic.css</code>). The original draft&#39;s premise (&quot;packages/ui is listed as yet to be published&quot;) is <strong>stale</strong> — confirming current npm publication status (has a version actually been published to the registry, distinct from being publish-configured) is the one open item here, not building the export.</li><li><code>grep -rn &quot;@sovereignfs/sdk&quot; packages/ui/src</code> returns <strong>no matches</strong> — the package already has zero coupling to the SDK or plugin contract, which the draft flagged as something &quot;worth flagging in review.&quot; It&#39;s already satisfied.</li><li><code>packages/ui/src/hooks/</code> (<code>useIsMobile.ts</code>, <code>useLongPress.ts</code>, <code>useDoubleTap.ts</code>, <code>useCommitOnEnterOrBlur.ts</code>) contain no <code>createContext</code>/<code>Provider</code> dependency — they&#39;re self-contained. The only <code>Provider</code>/<code>createContext</code> usage in the package is local to <code>Toast</code> and <code>Dialog</code> (own internal state, not a runtime-injected global), per <code>grep -rln &quot;createContext\\|Provider&quot; packages/ui/src</code>. No <code>SovereignUIRoot</code>-equivalent wrapper exists or is needed today.</li><li>Dark mode is driven by a <code>[data-theme=&#39;dark&#39;]</code> attribute selector in <code>packages/ui/src/tokens/semantic.css:91</code>, set at <code>:root</code> — not a <code>prefers-color-scheme</code> media query and not JS-context-dependent. An external app needs only to toggle that attribute itself; this is not currently documented anywhere outside the CSS source comment (<code>packages/ui/src/tokens/semantic.css:6</code>).</li><li><code>docs/design-system.md</code> has no &quot;standalone usage&quot; section — confirmed by search; the closest existing precedent for a tiered stability statement is <code>docs/sdk-stability.md</code>, which this RFC proposes mirroring rather than inventing a new format.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><ul><li>Changing the plugin-facing usage pattern, which works today and stays as-is.</li><li>Theming/rebrand support beyond exposing the existing token set — a separate, larger conversation.</li><li>Any <code>@sovereignfs/sdk</code> dependency, direct or transitive. The motivating consumer wants the component library and design tokens only — no session access, no plugin manifest, no runtime composition.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="_1-confirm-and-state-npm-publication-status" tabindex="-1">1. Confirm and state npm publication status <a class="header-anchor" href="#_1-confirm-and-state-npm-publication-status" aria-label="Permalink to &quot;1. Confirm and state npm publication status&quot;">​</a></h3><p>Confirm whether a version of <code>@sovereignfs/ui</code> has actually been published to the npm registry (publish-configured is not the same as published). State this plainly in <code>docs/design-system.md</code> so external consumers aren&#39;t guessing.</p><h3 id="_2-state-the-no-root-provider-required-guarantee-explicitly" tabindex="-1">2. State the &quot;no root provider required&quot; guarantee explicitly <a class="header-anchor" href="#_2-state-the-no-root-provider-required-guarantee-explicitly" aria-label="Permalink to &quot;2. State the &quot;no root provider required&quot; guarantee explicitly&quot;">​</a></h3><p>Per Current state, no context provider is required today. Rather than leaving this implicit, add an explicit statement to <code>docs/design-system.md</code>: components are pure CSS-variable/props consumers; no wrapper is required to use them outside the runtime shell. If a future component needs shared context (theme, density, locale), that becomes a breaking addition subject to the semver policy below — not a silent assumption.</p><h3 id="_3-state-hooks-are-runtime-independent" tabindex="-1">3. State hooks are runtime-independent <a class="header-anchor" href="#_3-state-hooks-are-runtime-independent" aria-label="Permalink to &quot;3. State hooks are runtime-independent&quot;">​</a></h3><p>Add an explicit compatibility guarantee for <code>useIsMobile</code>, <code>useLongPress</code>, <code>useDoubleTapHandler</code>, <code>useCommitOnEnterOrBlur</code>: &quot;these hooks have no dependency on the Sovereign runtime and are safe to use in any React 18+ app&quot; (per Current state, this is already true — the gap is only that it&#39;s undocumented).</p><h3 id="_4-add-a-standalone-usage-section-to-design-system-md" tabindex="-1">4. Add a &quot;standalone usage&quot; section to <code>design-system.md</code> <a class="header-anchor" href="#_4-add-a-standalone-usage-section-to-design-system-md" aria-label="Permalink to &quot;4. Add a &quot;standalone usage&quot; section to `design-system.md`&quot;">​</a></h3><p>A short, explicit section covering:</p><ul><li>Installation (<code>npm install @sovereignfs/ui</code>)</li><li>Importing tokens (<code>import &#39;@sovereignfs/ui/tokens.css&#39;</code> — already a valid import path per the existing <code>exports</code> map)</li><li>No required root wrapper (per §2)</li><li>Dark mode toggling outside the runtime shell: set <code>data-theme=&quot;dark&quot;</code> on the consumer&#39;s own <code>:root</code> (or <code>documentElement</code>), matching <code>[data-theme=&#39;dark&#39;]</code> in <code>packages/ui/src/tokens/semantic.css:91</code></li><li>A minimal working example (a form using <code>FormField</code> + <code>Input</code>)</li></ul><h3 id="_5-tiered-stability-statement-for-the-standalone-surface" tabindex="-1">5. Tiered stability statement for the standalone surface <a class="header-anchor" href="#_5-tiered-stability-statement-for-the-standalone-surface" aria-label="Permalink to &quot;5. Tiered stability statement for the standalone surface&quot;">​</a></h3><p><code>docs/sdk-stability.md</code> sets a precedent for a tiered stability statement. Mirror it for <code>@sovereignfs/ui</code>&#39;s standalone consumption surface: token names and core primitives (<code>Button</code>, <code>FormField</code>, <code>Input</code>, <code>Card</code>, tokens) are stable; editor-workflow primitives added for plugin-internal use (e.g. <code>SplitPane</code>, per epic task 9.16) may be marked experimental for standalone consumers if they carry assumptions not yet audited outside a plugin context.</p><h2 id="security-considerations" tabindex="-1">Security considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to &quot;Security considerations&quot;">​</a></h2><p>None expected — this is a pure client-side styling/component surface with no auth or data implications. Worth confirming during implementation that no component silently assumes a same-origin runtime API (e.g. an icon-loading endpoint) that wouldn&#39;t resolve correctly from an external domain — confirmed during implementation via <code>grep</code> across <code>packages/ui/src</code> for <code>fetch(</code>/<code>new URL(</code>/<code>src=&quot;/…&quot;</code>-style paths (zero matches); see the &quot;No same-origin or runtime-relative asset dependencies&quot; subsection this RFC added to <code>docs/design-system.md</code>.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Fork or vendor the token set</strong> into the external app instead of depending on the package directly. Rejected as a first choice — it immediately drifts from the source of truth and defeats the purpose of visual consistency across the ecosystem. A fallback only if the package genuinely can&#39;t be used standalone (Current state suggests it already can).</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><s>Are there icon assets served from a Sovereign-runtime-relative path that wouldn&#39;t resolve for an external consumer?</s> <strong>Resolved:</strong> no. Verified against the actual source (<code>grep</code> across <code>packages/ui/src</code> for <code>fetch(</code>, <code>new URL(</code>, and <code>src=&quot;/…&quot;</code>-style paths — zero matches). Icons are bundled as inline SVG React components at build time.</li><li><s>Should the tiered stability statement live entirely in <code>docs/design-system.md</code>, or get its own <code>docs/ui-stability.md</code>?</s><strong>Resolved:</strong> kept as a section in <code>docs/design-system.md</code>, per the recommendation — no separate doc needed yet.</li></ul><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Implemented in epic task 9.17 as a single documentation-only PR — no <code>packages/ui</code> code changes; verification confirmed none were needed. See the new &quot;Standalone usage&quot; section in <code>docs/design-system.md</code>.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>July 2026</td><td>Initial draft</td></tr><tr><td>0.2</td><td>July 2026</td><td>Implemented. Added the &quot;Standalone usage&quot; section to <code>docs/design-system.md</code>; resolved both open questions; confirmed npm publication status.</td></tr></tbody></table>',35)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
